head.b:skin:
    /*
    <Group description="🎨 Cores do Tema (PlayerOne)" selector=":root">
      <Variable name="gamer.primaria" description="Cor Neon Principal (Roxo)" type="color" default="#8b5cf6" value="#8b5cf6"/>
      <Variable name="gamer.secundaria" description="Cor Neon Secundária (Ciano)" type="color" default="#06b6d4" value="#06b6d4"/>
      <Variable name="gamer.fundo" description="Fundo do Site (Modo Escuro)" type="color" default="#0f172a" value="#0f172a"/>
    </Group>
    */

    /* MOTOR PLAYERONE V2.1 - CYBERPUNK EDITION */
    :root {
      --gamer-primary: $(gamer.primaria);
      --gamer-secondary: $(gamer.secundaria);
      --gamer-bg-dark: $(gamer.fundo);

      --font-main: 'Inter', sans-serif;
      --font-display: 'Oswald', sans-serif;
    }
    [data-bs-theme="dark"] {
      --gamer-bg: #0f172a;
      --gamer-surface: #1e293b;
      --gamer-text: #e2e8f0;
      --gamer-border: #334155;
    }

    body { background-color: var(--gamer-bg); color: var(--gamer-text); font-family: var(--font-text); -webkit-font-smoothing: antialiased; transition: background-color 0.3s ease, color 0.3s ease; }
    h1, h2, h3, h4, h5, h6, .oswald-font { font-family: var(--font-title); text-transform: uppercase; letter-spacing: 0.5px; }
    a { color: var(--gamer-primary); text-decoration: none; transition: all 0.3s ease; }
    a:hover { color: var(--gamer-secondary); }

    /* === TOPO E CABEÇALHO === */
    .top-bar { background-color: #020617; color: #94a3b8; font-size: 0.85rem; border-bottom: 1px solid #1e293b; }
    .top-bar a { color: #cbd5e1; }
    .top-bar a:hover { color: var(--gamer-primary); }

    header .navbar { background-color: var(--gamer-surface); border-bottom: 2px solid var(--gamer-border); padding: 15px 0; }
    .navbar-brand-wrapper h1 { margin: 0; font-size: 2rem; color: var(--gamer-text); }
    .navbar-nav .nav-link { font-family: var(--font-title); font-size: 1.1rem; color: var(--gamer-text); padding: 10px 15px !important; }
    .navbar-nav .nav-link:hover { color: var(--gamer-primary); }

    /* === CORREÇÕES DE IMAGENS DO POST === */
    .post-body-content img, .post-body-content iframe { max-width: 100% !important; height: auto !important; border-radius: 8px; margin: 1.5rem 0; box-shadow: 0 4px 15px rgba(0,0,0,0.2); }
    .separator a { margin-left: 0 !important; margin-right: 0 !important; }

    /* === BLOCKQUOTE ESTILIZADO (VERMELHO GAMER) === */
    .post-body-content blockquote {
      position: relative;
      background: linear-gradient(90deg, rgba(220, 38, 38, 0.08) 0%, transparent 100%);
      border-left: 4px solid #dc2626; 
      padding: 1.5rem 2rem;
      margin: 2rem 0;
      font-size: 1.2rem;
      font-style: italic;
      color: var(--gamer-text);
      border-radius: 0 8px 8px 0;
      box-shadow: inset 4px 0 10px -5px rgba(220, 38, 38, 0.2);
      z-index: 1;
    }
    .post-body-content blockquote::before {
      content: '\201C';
      font-family: var(--font-title);
      font-size: 6rem;
      position: absolute;
      left: 10px;
      top: -20px;
      color: #dc2626;
      opacity: 0.15;
      line-height: 1;
      z-index: -1;
    }
    [data-bs-theme="dark"] .post-body-content blockquote {
      background: linear-gradient(90deg, rgba(239, 68, 68, 0.15) 0%, transparent 100%);
    }

    /* === ESTILOS DOS CARTÕES DE JOGOS (HOME) === */
    .game-card {
      background-color: var(--gamer-surface);
      border: 1px solid var(--gamer-border);
      border-radius: 12px;
      overflow: hidden;
      transition: all 0.3s ease;
      height: 100%;
    }
    .game-card:hover {
      transform: translateY(-5px);
      border-color: var(--gamer-primary);
      box-shadow: 0 10px 25px rgba(139, 92, 246, 0.15);
    }
    .game-cover { position: relative; aspect-ratio: 16/9; overflow: hidden; background: #000; }
    .game-cover img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; opacity: 0.9; }
    .game-card:hover .game-cover img { transform: scale(1.05); opacity: 1; }

    .game-badge {
      position: absolute; top: 12px; left: 12px;
      background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
      color: #fff; font-family: var(--font-title); font-size: 0.8rem;
      padding: 4px 12px; border-radius: 20px; z-index: 2;
    }

    /* === SHORTCODE: CAIXA DE REVIEW === */
    .shortcode-review-box {
      background-color: #0f172a;
      border: 2px solid #1e293b;
      border-left: 5px solid var(--gamer-primary);
      border-radius: 12px;
      padding: 2rem;
      margin: 2.5rem 0;
      color: #e2e8f0;
      box-shadow: 0 10px 30px rgba(0,0,0,0.3);
      position: relative;
      overflow: hidden;
    }
    .shortcode-review-box::before {
      content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
      background: radial-gradient(circle, rgba(139,92,246,0.1) 0%, transparent 60%);
      pointer-events: none; z-index: 0;
    }
    .review-score-circle {
      width: 90px; height: 90px;
      background: #020617;
      border: 3px solid var(--gamer-secondary);
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-family: var(--font-title); font-size: 2.5rem; font-weight: 700; color: var(--gamer-secondary);
      box-shadow: 0 0 15px rgba(6, 182, 212, 0.4);
      text-shadow: 0 0 10px rgba(6, 182, 212, 0.8);
    }
    .review-bar-container { background: #1e293b; height: 8px; border-radius: 4px; overflow: hidden; margin-top: 8px; }
    .review-bar-fill { height: 100%; background: linear-gradient(90deg, var(--gamer-primary), var(--gamer-secondary)); border-radius: 4px; transition: width 1s ease-out; }

    /* === RODAPÉ === */
    footer { background-color: #020617; color: #94a3b8; border-top: 4px solid var(--gamer-primary); padding-top: 3rem; }
    .contact-form-widget .form-control { background-color: rgba(255,255,255,0.05) !important; border: 1px solid rgba(255,255,255,0.1) !important; color: #ffffff !important; border-radius: 8px; }
    .contact-form-widget .form-control:focus { border-color: var(--gamer-primary) !important; box-shadow: 0 0 0 0.25rem rgba(139,92,246,0.25) !important; }
    .contact-form-button-submit { background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary)); border: none !important; color: white !important; font-family: var(--font-title); font-size: 1.1rem; border-radius: 8px; padding: 10px 0; width: 100%; cursor: pointer;}

    .animate-up { opacity: 0; transform: translateY(20px); transition: 0.5s ease; }
    .animate-up.visible { opacity: 1; transform: translateY(0); }

    /* === PÁGINA DE ERRO 404 (GAME OVER) === */
    .error-404-wrapper {
      min-height: 55vh;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      text-align: center;
      background-color: var(--gamer-surface);
      border: 2px solid var(--gamer-border);
      border-radius: 12px;
      margin: 3rem auto;
      padding: 4rem 2rem;
      max-width: 800px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.1);
      position: relative;
      overflow: hidden;
    }
    .error-404-wrapper::before {
      content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
      background: radial-gradient(circle, rgba(139,92,246,0.05) 0%, transparent 60%);
      pointer-events: none; z-index: 0;
    }
    .error-code {
      font-size: clamp(6rem, 15vw, 10rem);
      color: var(--gamer-primary);
      text-shadow: 5px 5px 0 rgba(6, 182, 212, 0.4); /* Efeito 3D/Glitch Ciano */
      line-height: 1;
      margin-bottom: 0;
      position: relative;
      z-index: 1;
    }
    .error-icon i {
      color: var(--gamer-secondary);
      font-size: 5rem;
      filter: drop-shadow(0 0 15px rgba(6, 182, 212, 0.5));
      position: relative;
      z-index: 1;
    }
    .error-content {
      position: relative;
      z-index: 1;
    }
    .btn-respawn {
      background: linear-gradient(45deg, var(--gamer-primary), var(--gamer-secondary));
      color: #fff !important;
      border: none;
      font-family: var(--font-title);
      letter-spacing: 1px;
      text-transform: uppercase;
      padding: 12px 35px;
      border-radius: 30px;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }
    .btn-respawn:hover {
      transform: scale(1.05);
      box-shadow: 0 8px 25px rgba(139,92,246,0.4);
    }

    [data-bs-theme="dark"] .error-404-wrapper {
      box-shadow: 0 10px 30px rgba(0,0,0,0.4);
    }

    /* === ESTILIZAÇÃO PREMIUM DAS TAGS (PLAYERONE EDITION) === */
    .list-label-widget-content ul {
      list-style: none !important;
      padding: 0 !important;
      margin: 0 !important;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .list-label-widget-content ul li {
      display: inline-flex;
      align-items: center;
      margin: 0;
    }

    .list-label-widget-content ul li a,
    .post-bottom-tags a {
      display: inline-flex;
      align-items: center;
      background: var(--gamer-surface);
      color: var(--gamer-text);
      font-family: var(--font-title); /* Usa a fonte Oswald */
      font-size: 0.9rem;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 1px;
      padding: 8px 20px;
      border-radius: 4px; /* Cantos menos redondos (ar mais tech/gamer) */
      border: 1px solid var(--gamer-border);
      transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
      text-decoration: none !important;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    }

    /* Ícone de Tag (Gamer Vibe) */
    .list-label-widget-content ul li a::before,
    .post-bottom-tags a::before {
      content: '\F325'; /* Código do ícone bi-controller do Bootstrap */
      font-family: 'bootstrap-icons';
      margin-right: 8px;
      font-size: 1rem;
      color: var(--gamer-primary);
      transition: color 0.3s ease;
    }

    /* Efeito Flutuante e Brilho Neon ao Hover */
    .list-label-widget-content ul li a:hover,
    .post-bottom-tags a:hover {
      background: var(--gamer-primary);
      color: #ffffff !important;
      border-color: var(--gamer-primary);
      transform: translateY(-3px);
      box-shadow: 0 8px 20px rgba(139, 92, 246, 0.4); /* Sombra Roxo Neon */
    }

    /* O ícone fica branco no hover */
    .list-label-widget-content ul li a:hover::before,
    .post-bottom-tags a:hover::before {
      color: #ffffff;
    }

    /* Contador de Posts (Design de Level/Badge) */
    .list-label-widget-content ul li span[dir='ltr'] {
      background: var(--gamer-secondary); /* Azul Ciano */
      color: #ffffff;
      font-family: var(--font-title);
      font-size: 0.8rem;
      padding: 2px 8px;
      border-radius: 4px;
      margin-left: -12px; 
      font-weight: 700;
      z-index: 2;
      border: 2px solid var(--gamer-bg);
      box-shadow: 0 2px 5px rgba(0,0,0,0.3);
    }
/* --- Popular Posts: Thumbnail (Mobile First) --- */
.popular-posts .item-thumbnail {
  /* Garante que a caixa da imagem não encolhe e mantém a margem do lado direito */
  flex-shrink: 0;
  margin-right: 15px;
}

.popular-posts .item-thumbnail img {
  /* Tamanho base para telemóveis: mais pequeno para não quebrar o layout */
  width: 100px;
  height: 56px; /* Mantém a proporção 16:9 */
  object-fit: cover;
  border-radius: 8px;
  display: block;
  transition: all 0.3s ease;
}

/* --- Breakpoint para Tablets e Desktop (Bootstrap md >= 768px) --- */
@media (min-width: 768px) {
  .popular-posts .item-thumbnail img {
    /* O tamanho HD em 16:9 que espetámos no pedido XML */
    width: 150px;
    height: 85px; 
  }
}

b:includable.script:
function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
  //
  document.addEventListener('DOMContentLoaded', () => {

    /* 1. DARK MODE NATIVO */
    const setTheme = t => { document.documentElement.setAttribute('data-bs-theme', t); localStorage.setItem('theme', t); document.querySelector('.btn-dark-mode i').className = t === 'dark' ? 'bi bi-sun-fill fs-6 text-warning' : 'bi bi-moon-stars-fill fs-6'; };
    setTheme(localStorage.getItem('theme') || 'dark');
    document.querySelectorAll('.btn-dark-mode').forEach(b => b.addEventListener('click', () => setTheme(document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark')));

    /* 2. SCROLL ANIMATIONS */
    const obs = new IntersectionObserver(es => es.forEach(e => { if(e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); } }), {threshold: 0.1});
    document.querySelectorAll('.animate-up, .game-card').forEach((el, i) => { if(el.classList.contains('game-card')) el.style.transitionDelay = `${(i % 2) * 0.1}s`; el.classList.add('animate-up'); obs.observe(el); });

    /* =================================================================
       3. MOTOR DE SHORTCODES (VANILLA JS CUSTOMIZADO)
       Transforma [review ...] numa caixa de pontuação espetacular
       ================================================================= */

    // Procura o conteúdo da postagem (apenas se existir na página)
    const postBodies = document.querySelectorAll('.post-body-content');

    postBodies.forEach(post => {
      let contentHtml = post.innerHTML;

      // Regex para encontrar a tag [review ...]
      const reviewRegex = /\[review\s+([^\]]+)\]/gi;

      // Se encontrar o shortcode, faz a substituição mágica
      if (reviewRegex.test(contentHtml)) {

        contentHtml = contentHtml.replace(reviewRegex, (match, atributosString) => {

          // Extrai os atributos usando outra Regex (ex: nota="9")
          const attrs = {};
          const extractRegex = /(\w+)="([^"]+)"/g;
          let attrMatch;
          while ((attrMatch = extractRegex.exec(atributosString)) !== null) {
            attrs[attrMatch[1]] = attrMatch[2];
          }

          // Valores por defeito caso o utilizador se esqueça de preencher algo
          const titulo = attrs.titulo || 'Veredicto Final';
          const notaFinal = attrs.nota || '0.0';
          const valGrafico = attrs.grafico || '0';
          const valSom = attrs.som || '0';
          const valGameplay = attrs.gameplay || '0';

          // Constrói o HTML final da Review Box (Estilo Cyberpunk/Neon)
          return `
            <div class="shortcode-review-box z-1">
              <div class="row align-items-center position-relative z-1">

                <div class="col-md-8 mb-4 mb-md-0">
                  <h3 class="oswald-font fs-3 text-white mb-4 d-flex align-items-center gap-2">
                    <i class="bi bi-controller text-primary"></i> ${titulo}
                  </h3>

                  <div class="mb-3">
                    <div class="d-flex justify-content-between small fw-bold mb-1 text-uppercase text-secondary"><span>Gráficos</span><span>${valGrafico}/10</span></div>
                    <div class="review-bar-container"><div class="review-bar-fill" style="width: ${valGrafico}0%;"></div></div>
                  </div>

                  <div class="mb-3">
                    <div class="d-flex justify-content-between small fw-bold mb-1 text-uppercase text-secondary"><span>Som / Trilha</span><span>${valSom}/10</span></div>
                    <div class="review-bar-container"><div class="review-bar-fill" style="width: ${valSom}0%;"></div></div>
                  </div>

                  <div class="mb-2">
                    <div class="d-flex justify-content-between small fw-bold mb-1 text-uppercase text-secondary"><span>Jogabilidade</span><span>${valGameplay}/10</span></div>
                    <div class="review-bar-container"><div class="review-bar-fill" style="width: ${valGameplay}0%;"></div></div>
                  </div>
                </div>

                <div class="col-md-4 d-flex justify-content-center border-start border-secondary border-opacity-25">
                  <div class="text-center">
                    <div class="small fw-bold text-uppercase text-primary mb-2" style="letter-spacing: 2px;">Nota Final</div>
                    <div class="review-score-circle mx-auto">${notaFinal}</div>
                  </div>
                </div>

              </div>
            </div>
          `;
        });

        // Atualiza o HTML do post com a caixa renderizada
        post.innerHTML = contentHtml;
      }
    });


// Ripple Effect Bare-Metal
document.querySelectorAll('.btn, .nav-link').forEach(button => {
  button.addEventListener('click', function(e) {
    let x = e.clientX - e.target.getBoundingClientRect().left;
    let y = e.clientY - e.target.getBoundingClientRect().top;

    let ripple = document.createElement('span');
    ripple.style.left = x + 'px';
    ripple.style.top = y + 'px';
    ripple.classList.add('ripple-effect');

    this.appendChild(ripple);

    setTimeout(() => { ripple.remove(); }, 600);
  });
});






  });
  //
